<?php
require '../config/app.php';require_role(['admin','staff']);$title='Manage Appointments';$basePath='../';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];$tech=(int)$_POST['technician_id'];$status=$_POST['status'];$allowed=['Booked','Confirmed','Arrived','In Progress','Completed','Cancelled'];if(!in_array($status,$allowed,true))$status='Booked';$st=$pdo->prepare("UPDATE appointments SET technician_id=?,status=? WHERE id=?");$st->execute([$tech?:null,$status,$id]);flash('success','Appointment updated.');redirect('appointments.php');}
$techs=$pdo->query("SELECT id,name FROM users WHERE role='technician' ORDER BY name")->fetchAll();$rows=$pdo->query("SELECT a.*,p.name patient_name,t.name test_name,te.name technician_name,py.status payment_status FROM appointments a JOIN users p ON p.id=a.patient_id JOIN diagnostic_tests t ON t.id=a.test_id LEFT JOIN users te ON te.id=a.technician_id LEFT JOIN payments py ON py.appointment_id=a.id ORDER BY a.appointment_date DESC,a.appointment_time DESC")->fetchAll();require '../partials/header.php';?>
<div class="card p-3"><h4>Appointments</h4><div class="table-responsive"><table class="table"><thead><tr><th>Patient/Test</th><th>Date</th><th>Payment</th><th>Technician</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="patient_details.php?id=<?=$r['patient_id']?>" class="text-decoration-none fw-semibold"><?=e($r['patient_name'])?></a><br><small><?=e($r['test_name'])?></small></td><td><?=e($r['appointment_date'])?><br><?=date('h:i A',strtotime($r['appointment_time']))?></td><td><?=e($r['payment_status']??'Pending')?></td><td><?=e($r['technician_name']??'Unassigned')?></td><td><?=e($r['status'])?></td><td><form method="post" class="d-flex gap-1"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select class="form-select form-select-sm" name="technician_id"><option value="0">Unassigned</option><?php foreach($techs as $t):?><option value="<?=$t['id']?>" <?=$r['technician_id']==$t['id']?'selected':''?>><?=e($t['name'])?></option><?php endforeach;?></select><select class="form-select form-select-sm" name="status"><?php foreach(['Booked','Confirmed','Arrived','In Progress','Completed','Cancelled'] as $s):?><option <?=$r['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn btn-sm btn-primary">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div>
<?php require '../partials/footer.php'; ?>
